"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2921],{42921:t=>{t.exports=JSON.parse('{"slug":"byudzhet-2027-pensii-mrot-nalog-vklady","locale":"zh","title":"政府提交2027–2029年预算，2027年赤字为5.5万亿卢布","description":"2027年预算：赤字5.5万亿卢布，养老金上涨10.3%，最低工资28 935卢布。存款税最高22%影响谁，以及赤字为何支撑高利率。","blocks":[{"id":"b001","kind":"paragraph","text":"政府于2026年九月30日向国家杜马提交2027–2029年预算。2027年计划支出48.8万亿卢布，收入43.3万亿，差额5.5万亿称为财政赤字，占GDP的2.2%。2028和2029年的缺口相近，分别5.1和5.3万亿卢布。"},{"id":"b002","kind":"paragraph","text":"2027年养老金将两次上调：二月1日起6.8%，四月1日起再加3.3%，复合约10.3%（1.068 \xd7 1.033）。年末平均老年养老金为29 904卢布。最低工资涨6.8%至28 935卢布，最低生活标准增至20 227卢布。三年内儿童及家庭项目安排10万亿卢布。"},{"id":"b003","kind":"paragraph","text":"2026年九月30日随预算一同提交的还有税法修正案。提议把存款利息、股息与证券收益并入工资，按13%至22%的统一阶梯征税。年收入不超过2.4百万卢布、即月均200千卢布，仍适用13%。存款利息免税额度保留。财政部估计影响不超过6%的纳税人，约4百万人。"},{"id":"b004","kind":"paragraph","text":"赤字为何与每个人有关？设想家庭收入100千卢布，支出113千，差额靠借款。2027年预算比例相同（48.8 / 43.3 = 1.13）。超收入支出成为别人的工资和购买力。有钱买东西的人更多，商品数量不变，价格便涨得更快。"},{"id":"b005","kind":"paragraph","text":"同在九月30日，俄罗斯央行向杜马提交2027–2029年政策战略，专章讨论预算。目标仍为约4%通胀。当前高于目标，九月7日为6.3%，关键利率14%。政府举债支出越大，央行维持高利率越久；房贷、其他贷款和存款利率都受其影响。下次利率决定在十月23日。"},{"id":"b006","kind":"paragraph","text":"对普通人的含义：养老金增10.3%，最低工资增6.8%，央行预计2027年通胀约4%。新存款税阶梯只涉及工资加利息年收入超过2.4百万卢布者。押注利率很快下降而借房贷有风险，因为赤字可能推迟降息；等降息再买也有成本，因为期间物价继续涨。杜马审议后哪些数字保留，仍未知。"},{"id":"b007","kind":"heading","text":"2027年养老金会上涨多少？"},{"id":"b008","kind":"paragraph","text":"保险养老金二月1日上调6.8%，四月1日再调3.3%，合计约10.3%。2027年末平均老年养老金为29 904卢布。"},{"id":"b009","kind":"heading","text":"存款利息会征22%税吗？"},{"id":"b010","kind":"paragraph","text":"只有收入极高者。2026年九月30日提交的修正案保留年收入连工资不超过2.4百万卢布的13%税率，22%从50百万卢布起适用。存款利息免税额度仍在。法案尚待通过。"},{"id":"b011","kind":"heading","text":"2027年最低工资是多少？"},{"id":"b012","kind":"paragraph","text":"28 935卢布，比现在高6.8%。最低生活标准将升至20 227卢布。"}],"sources":[{"label":"政府向杜马提交下一三年期预算草案","url":"https://www.vedomosti.ru/economics/articles/2026/09/30/1233234-proekt-byudzheta-na-20272029-godi"},{"label":"政府提交2027–2029年预算草案","url":"https://www.kommersant.ru/doc/8990879"},{"label":"政府向杜马提交2027–2029年预算案","url":"https://ria.ru/20260930/gosduma-2121326719.html"},{"label":"2027–2029年预算：收支、最低工资与生育资本调整","url":"https://finance.mail.ru/article/pravitelstvo-vneslo-v-gd-proekt-byudzheta-na-20272029-gody-69230340/"},{"label":"2027年起的存款利息及投资收益税","url":"https://t-j.ru/taxation-changes/"},{"label":"最高22%存款税：财政部建议将影响谁","url":"https://finuslugi.ru/navigator/nakopit-i-sohranit/stat_nalog-22-na-vklady-komu-gotovitsya"},{"label":"财政部建议将累进个人所得税扩展至被动收入","url":"https://amp.rbc.ru/rbcnews/economics/24/09/2026/6ab4dd2e8788480e67fe300e"},{"label":"税法修正草案纳入预算方案","url":"https://investfuture.ru/articles/proekt-izmenenii-v-nalogovyi-kodeks-voshel-v-byudzhetnyi-paket-3f16ce8bddcfe833"},{"label":"俄罗斯央行将关键利率维持在14%","url":"https://www.cbr.ru/press/keypr/"},{"label":"央行向杜马提交货币政策主要方向草案","url":"https://www.vedomosti.ru/economics/news/2026/09/30/1233154-tsb-napravil-gosdumu"}],"sourceBodySha256":"be77690376518f39ef24e28cfc00950eded08b6fb2c56a9ff24881d083267c1d"}')}}]);